import { v4 as uuidv4 } from 'uuid';
import {
  Artifact,
  ArtifactVersion,
  CreateArtifactInput,
  UpdateArtifactInput,
  SearchCriteria,
  PaginationOptions,
} from '../types';
import { StorageService } from './StorageService';

export class ArtifactService {
  private storage: StorageService;

  constructor(storage: StorageService) {
    this.storage = storage;
  }

  async create(input: CreateArtifactInput): Promise<Artifact> {
    const now = new Date();
    const artifact: Artifact = {
      id: uuidv4(),
      contextId: input.contextId,
      name: input.name,
      content: input.content,
      mimeType: input.mimeType || 'text/plain',
      version: 1,
      tags: input.tags || [],
      metadata: input.metadata || {},
      createdAt: now,
      updatedAt: now,
    };

    await this.storage.saveArtifact(artifact);
    await this.storage.saveVersion(artifact.id, {
      version: 1,
      content: artifact.content,
      createdAt: now,
      metadata: artifact.metadata,
    });

    return artifact;
  }

  async get(id: string, version?: number): Promise<Artifact | null> {
    const artifact = await this.storage.getArtifact(id);
    if (!artifact) return null;

    if (version && version !== artifact.version) {
      const historicalVersion = await this.storage.getVersion(id, version);
      if (historicalVersion) {
        return {
          ...artifact,
          version: historicalVersion.version,
          content: historicalVersion.content,
          metadata: historicalVersion.metadata,
        };
      }
      return null;
    }

    return artifact;
  }

  async update(id: string, input: UpdateArtifactInput): Promise<Artifact | null> {
    const artifact = await this.storage.getArtifact(id);
    if (!artifact) return null;

    const now = new Date();
    const newVersion = artifact.version + 1;

    const updated: Artifact = {
      ...artifact,
      name: input.name ?? artifact.name,
      content: input.content ?? artifact.content,
      mimeType: input.mimeType ?? artifact.mimeType,
      tags: input.tags ?? artifact.tags,
      metadata: { ...artifact.metadata, ...input.metadata },
      version: newVersion,
      updatedAt: now,
    };

    await this.storage.saveArtifact(updated);

    if (input.content !== undefined) {
      await this.storage.saveVersion(id, {
        version: newVersion,
        content: input.content,
        createdAt: now,
        metadata: updated.metadata,
      });
    }

    return updated;
  }

  async delete(id: string): Promise<boolean> {
    return this.storage.deleteArtifact(id);
  }

  async getVersions(id: string): Promise<ArtifactVersion[]> {
    return this.storage.getVersions(id);
  }

  async search(
    criteria: SearchCriteria,
    pagination?: PaginationOptions
  ): Promise<Artifact[]> {
    return this.storage.searchArtifacts(criteria, pagination);
  }

  async getByContext(
    contextId: string,
    pagination?: PaginationOptions
  ): Promise<Artifact[]> {
    return this.search({ contextId }, pagination);
  }
}
